def resolve(path, cwd, links):
    if not path or not cwd or links is None:
        return None

    # Normalize cwd to remove trailing slash
    if cwd != '/' and cwd.endswith('/'):
        return None

    # Start with the initial path
    if path.startswith('/'):
        current = '/'
        components = path.split('/')[1:]
    else:
        current = cwd
        components = path.split('/')

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        comp = components[i]

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            i += 1
            continue

        # Handle '..'
        if comp == '..':
            if current == '/':
                pass  # Stay at root
            else:
                # Move to parent
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Any other name: append it
        if current == '/':
            new_path = '/' + comp
        else:
            new_path = current + '/' + comp

        # Check if it's a symlink
        if new_path in links:
            link_count += 1
            if link_count > max_links:
                return None

            # Get the target
            target = links[new_path]

            # If target doesn't start with '/', it's relative to the directory containing the link
            if not target.startswith('/'):
                # Directory containing the link is new_path's parent
                if new_path == '/':
                    link_dir = '/'
                else:
                    link_dir = new_path.rsplit('/', 1)[0]
                    if link_dir == '':
                        link_dir = '/'

                if link_dir == '/':
                    target = '/' + target
                else:
                    target = link_dir + '/' + target

            # Parse the target and continue from there
            target_components = target.split('/')[1:] if target.startswith('/') else target.split('/')

            # Continue resolution with remaining components from target, then remaining original components
            remaining = components[i+1:]
            components = target_components + remaining

            # Reset to root if target is absolute
            if target.startswith('/'):
                current = '/'

            i = 0
            continue

        # Normal component: just update current
        current = new_path
        i += 1

    # Return result
    if current == '':
        return '/'
    return current

